insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-allied-health-administration') and position=1),'how-australian-allied-health-practices-operate','How Australian Allied Health Practices Operate','Allied health practices may include physiotherapy, occupational therapy, psychology, speech pathology, podiatry, dietetics, exercise physiology, and other professions. A VA may support the practice, but practitioners remain responsible for clinical assessment, treatment, advice, and professional obligations.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize common allied health practice roles","Understand the patient administrative journey","Separate clinical decisions from VA administration"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Allied health practices may include physiotherapy, occupational therapy, psychology, speech pathology, podiatry, dietetics, exercise physiology, and other professions. A VA may support the practice, but practitioners remain responsible for clinical assessment, treatment, advice, and professional obligations."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["A patient journey can include enquiry, intake, referral, booking, reminder, appointment, billing, follow-up, recall, and record administration.","Practice owners, practitioners, reception/admin staff, billers, referrers, funders, and patients have different roles.","Appointment types, practitioner scope, referral requirements, and billing pathways vary by practice.","The VA should follow the practice''s written workflow rather than infer clinical urgency or eligibility."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Map the practice services and practitioners.","Identify patient-management, email, phone, document, and billing systems.","List what the VA may handle independently.","List clinical, privacy, billing, complaint, and emergency matters that must be escalated.","Learn the practice''s appointment types, cancellation rules, referral process, and handoff contacts.","Document the workflow."]},{"type":"callout","title":"Stay inside the role","text":"Do not give clinical advice, interpret symptoms, recommend treatment, alter clinical notes, or tell a patient which service is clinically appropriate unless the practice has an approved administrative routing script."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Treating all allied health professions as interchangeable","Giving appointment advice based on symptoms","Changing practitioner notes","Using personal messaging accounts for patient information","Assuming a referral is valid without following the practice checklist"]},{"type":"scenario","title":"Practice scenario","text":"A new patient says they have severe shoulder pain and asks whether they need physiotherapy or another provider. Gather only approved intake information and route the clinical question to the practice."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Know the practice structure.","Keep clinical judgment with practitioners.","Use written intake and escalation rules.","Preserve patient context safely."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-allied-health-administration') and position=1),'australian-privacy-and-health-information-for-practice-admin','Australian Privacy and Health Information for Practice Admin','Health information is sensitive personal information. Australian privacy rules and professional obligations can apply differently depending on the practice and jurisdiction, but a VA should consistently use approved systems and minimum necessary data.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize health information as highly sensitive","Apply minimum-necessary access","Handle privacy incidents through the practice process"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Health information is sensitive personal information. Australian privacy rules and professional obligations can apply differently depending on the practice and jurisdiction, but a VA should consistently use approved systems and minimum necessary data."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Patient identity, contact information, health details, referrals, clinical notes, billing information, and identifiers may be sensitive.","The Australian Privacy Principles address collection, use/disclosure, data quality, security, access, and correction in covered organizations.","Offshore access requires the practice to use appropriate controls; the VA should not invent the legal framework.","Wrong-recipient emails, exposed links, lost devices, and copied data can create privacy incidents."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Use only the access level required for your tasks.","Verify patient identity using the practice''s approved process.","Avoid downloading entire records when the task needs one field.","Use approved systems for documents and messaging.","Check recipients before sending sensitive information.","Report suspected privacy incidents immediately.","Document correction requests rather than editing records outside process."]},{"type":"callout","title":"Stay inside the role","text":"This course is not legal privacy advice. Questions about legislation, cross-border disclosure, mandatory reporting, or legal notification belong with the practice''s privacy, legal, or compliance owner."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Using shared logins when individual access is available","Sending referrals to the wrong provider email","Copying patient data into unapproved AI tools","Discussing patient details in open team channels","Deleting evidence after a mistaken send"]},{"type":"scenario","title":"Practice scenario","text":"A referral PDF is accidentally attached to an email addressed to the wrong patient. Describe the immediate administrative actions without deciding the legal notification outcome yourself."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Health data deserves high protection.","Use minimum necessary access.","Do not hide privacy mistakes.","Keep legal interpretation with the responsible owner."]}]'::jsonb,30,2,false,1,null,null,now(),now())
