on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-allied-health-administration') and position=2),'patient-intake-forms-and-demographic-checks','Patient Intake, Forms, and Demographic Checks','Good intake helps the practice identify the patient, contact them, bill correctly, and prepare the practitioner. The VA''s role is completeness and routing, not diagnosis.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Collect approved intake information consistently","Identify missing administrative data","Avoid turning intake into clinical assessment"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Good intake helps the practice identify the patient, contact them, bill correctly, and prepare the practitioner. The VA''s role is completeness and routing, not diagnosis."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Practices may require identity, contact, emergency contact, referral, funding, consent, and appointment information.","Mandatory fields vary by practice and service.","Patient-provided information should be recorded accurately, not rewritten into a clinical conclusion.","Consent and communication preferences should be handled under the practice workflow."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Use the approved intake form or checklist.","Verify core contact details.","Check required documents are attached.","Flag missing or conflicting information.","Route clinical answers or symptom details to the practitioner if needed.","Save information in the designated patient record.","Create the next booking/referral task."]},{"type":"callout","title":"Stay inside the role","text":"Do not edit a patient''s description to sound more clinical or decide whether symptoms meet a treatment criterion."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Collecting extra information because it may be useful later","Guessing gender, diagnosis, funding status, or relationship","Creating duplicate patient records","Leaving referrals in email instead of the patient system","Using clinical labels from your own interpretation"]},{"type":"scenario","title":"Practice scenario","text":"A patient submits an intake form with two different mobile numbers and an incomplete referral. Explain how you clean the administrative record without inventing information."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Collect only what the workflow needs.","Preserve patient wording.","Flag missing information.","Keep records in the source system."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-allied-health-administration') and position=2),'referrals-documents-and-practitioner-handoffs','Referrals, Documents, and Practitioner Handoffs','Referrals and supporting documents can affect whether a practice has the information it needs before an appointment. Administrative tracking prevents documents from getting lost without requiring the VA to interpret clinical content.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Track referral status","Route documents to the correct practitioner","Create clear outstanding-item visibility"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Referrals and supporting documents can affect whether a practice has the information it needs before an appointment. Administrative tracking prevents documents from getting lost without requiring the VA to interpret clinical content."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["A referral may have sender, patient, date, intended practitioner/service, supporting documents, and administrative validity checks.","Practices may use different rules for private-pay, insurer, GP, NDIS, workers compensation, or other funding pathways.","The VA can track receipt and completeness using approved criteria.","Clinical relevance and treatment decisions belong to practitioners."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Identify the patient safely.","Attach the referral to the correct record.","Record source and received date.","Check the practice''s required administrative fields.","Flag missing pages, unreadable documents, or missing identifiers.","Notify the intended practitioner/team according to urgency rules.","Create a follow-up task for outstanding documents."]},{"type":"callout","title":"Stay inside the role","text":"Do not interpret referral diagnoses, urgency, treatment recommendations, or clinical suitability."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Attaching a referral to the wrong patient","Marking a referral valid based on your own understanding","Failing to notify a practitioner of an expected document","Emailing documents through unapproved channels","Letting missing documents sit with no follow-up"]},{"type":"scenario","title":"Practice scenario","text":"A referral arrives for a patient whose surname and date of birth match two existing records. Explain the safe identity-resolution process before attaching it."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Identity first.","Track documents from evidence.","Use approved administrative checks only.","Route clinical interpretation."]}]'::jsonb,30,2,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

