insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-allied-health-administration') and position=3),'scheduling-appointment-types-reminders-and-no-shows','Scheduling, Appointment Types, Reminders, and No-Shows','Allied health calendars may have different appointment lengths, practitioner skills, locations, telehealth rules, buffers, rooms, and funding requirements. The VA must follow the practice''s scheduling matrix.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Book the correct administrative appointment type","Use practitioner and location rules","Manage reminders, changes, and no-shows consistently"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Allied health calendars may have different appointment lengths, practitioner skills, locations, telehealth rules, buffers, rooms, and funding requirements. The VA must follow the practice''s scheduling matrix."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Appointment type determines duration and may affect practitioner/location requirements.","New and returning patients may have different booking steps.","Reminder and cancellation workflows should match practice policy.","Clinical urgency cannot be inferred from a calendar gap.","No-show handling may affect fees, follow-up, and practitioner review."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Identify the approved appointment type from the practice workflow.","Check practitioner/location availability.","Confirm time zone for telehealth or interstate patients.","Verify required referral/forms status if required.","Book and send approved confirmation.","Ensure reminders are configured or queued.","Record cancellation/reschedule/no-show outcome.","Escalate unusual clinical or complaint issues."]},{"type":"callout","title":"Stay inside the role","text":"Do not squeeze a clinically different appointment into a shorter type just because there is availability."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Booking the wrong appointment duration","Ignoring practitioner-specific rules","Promising fee waivers for late cancellation","Sending reminders against patient preferences","Deciding a symptom means the patient needs an urgent slot"]},{"type":"scenario","title":"Practice scenario","text":"A patient asks to book a 15-minute slot for an issue the practice normally handles as a 45-minute initial appointment. Explain the safe admin response."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Use the scheduling matrix.","Respect appointment-type rules.","Keep fee exceptions with authorized staff.","Do not convert symptoms into clinical triage."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-allied-health-administration') and position=3),'recalls-waitlists-and-routine-patient-messages','Recalls, Waitlists, and Routine Patient Messages','Patients may need reminders to book follow-up care, return forms, reschedule, or respond to administrative requests. A good system makes the task visible without the VA deciding whether care is clinically necessary.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Manage recurring admin follow-up","Use waitlists and recalls without losing context","Write clear non-clinical patient communication"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Patients may need reminders to book follow-up care, return forms, reschedule, or respond to administrative requests. A good system makes the task visible without the VA deciding whether care is clinically necessary."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Recall timing should come from practitioner instruction or approved protocol.","Waitlists need preferences, availability, and status.","Routine messages should avoid clinical interpretations.","Patient replies can change whether automation remains appropriate.","Repeated non-response should follow the practice''s escalation/closure process."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Create recalls from practitioner-approved instructions.","Record reason, due date, and owner.","Use approved reminder cadence.","Update waitlist availability from confirmed patient preferences.","Stop or change messages when the patient responds.","Escalate clinical questions or distress.","Close the task only under practice rules."]},{"type":"callout","title":"Stay inside the role","text":"Do not create a clinical recall interval from your own judgment or tell a patient they need treatment because a task exists."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Setting recall dates by habit","Sending repeated reminders after a patient declines","Leaving waitlist preferences outdated","Writing clinical explanations into admin messages","Closing follow-up with no documented reason"]},{"type":"scenario","title":"Practice scenario","text":"A recall task says ''contact in 6 weeks'' but the record does not show who created it. Explain how you validate it before contacting the patient."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Recall from evidence.","Keep waitlists current.","Adjust automation to replies.","Keep clinical rationale with practitioners."]}]'::jsonb,30,2,false,1,null,null,now(),now())
