insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-allied-health-administration') and position=4),'billing-administration-funding-pathways-and-outstanding-accounts','Billing Administration, Funding Pathways, and Outstanding Accounts','Allied health practices may bill private patients, insurers, government programs, employers, plan managers, or other third parties. The VA needs to follow the practice''s billing matrix and preserve supporting evidence.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Support routine allied-health billing","Recognize different funding/third-party pathways","Route billing interpretation and disputes"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Allied health practices may bill private patients, insurers, government programs, employers, plan managers, or other third parties. The VA needs to follow the practice''s billing matrix and preserve supporting evidence."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Billing rules vary by payer and service.","Invoices should reflect approved appointment/service information.","Provider numbers, claim references, referrals, or supporting documents may be required in some workflows.","Outstanding balances should be followed up under policy.","Coding, eligibility, clinical service selection, and regulated billing interpretation belong to qualified or authorized staff."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm the appointment/service record is ready for billing.","Use the approved payer pathway.","Check required administrative fields and supporting documents.","Create or send invoice/claim preparation if authorized.","Record payment or outstanding status.","Follow up using approved reminders.","Escalate rejected claims, disputes, unusual coding, or eligibility questions."]},{"type":"callout","title":"Stay inside the role","text":"Do not choose clinical billing codes, determine funding eligibility, alter provider numbers, or make regulated claim decisions unless that is explicitly within your qualified role."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Billing from a calendar entry without checking service status","Changing a code to make a claim pass","Assuming all third-party payers use the same workflow","Sending sensitive billing data to the wrong recipient","Writing off balances to clear reports"]},{"type":"scenario","title":"Practice scenario","text":"A third-party payer rejects an invoice because a field appears inconsistent with the referral. Explain what you can check administratively and what must be reviewed by the practice."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Follow the billing matrix.","Use source records.","Keep coding and eligibility judgment with the right owner.","Track rejected items to resolution."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-allied-health-administration') and position=4),'australian-allied-health-composite-admin-simulation','Australian Allied Health Composite Admin Simulation','This simulation tests whether you can support a practice without drifting into clinical work.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Run a mixed practice admin queue","Prioritize privacy, patient, scheduling, referral, and billing issues","Produce a safe handoff"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"This simulation tests whether you can support a practice without drifting into clinical work."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Privacy","Intake","Referrals","Scheduling","Recalls","Billing","Complaints and escalation"]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review the fictional queue.","Identify privacy or urgent-practice escalations.","Complete routine intake/referral administration.","Resolve scheduling and reminder tasks.","Prepare a billing exception.","Draft non-clinical patient messages.","Produce an end-of-day practitioner/admin handoff."]},{"type":"callout","title":"Stay inside the role","text":"The simulation deliberately includes clinical and funding questions. Your job is to route them correctly, not answer them."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Trying to be helpful with clinical advice","Over-collecting health data","Changing appointment type to fit the calendar","Editing billing codes to clear rejections","Failing to escalate a privacy incident"]},{"type":"scenario","title":"Practice scenario","text":"A fictional allied health clinic has a misdirected referral email, a new patient with missing forms, a practitioner schedule conflict, a recall with unclear origin, a rejected third-party invoice, and a patient asking whether their symptoms require urgent treatment. Build the safe work queue and handoff."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Protect health information.","Use practice rules.","Keep clinical judgment with practitioners.","Document exceptions clearly."]}]'::jsonb,30,2,false,1,null,null,now(),now())
